      document.body.insertBefore(banner, document.body.firstChild);
    }
  }

  function boot2() {
    initIntegrity();
    buildToolbar();
    initCursorBox();
    initKeyboard();
    renderTimeline();
    /* 深链：#e10 选中事件 · #c=8 设置游标 · #f=incident,rollback 类型过滤 */
    var h = location.hash || "";
