/* =====================================================================
 * AURORA 变更时间轴 — 样式（深色专业运维工具）
 *
 * 色彩通道分工（经 dataviz 校验器验证，dark surface #1a1a19）：
 *   分类色（中性操作：发版/配置/扩缩容）→ 校验通过的 3 槽位
 *   状态色（故障/回滚/修复、健康度）    → 固定状态色板，恒以 icon+label 出现
 *   文本一律用 ink 令牌，颜色只出现在标记上
 * ===================================================================== */

:root {
  color-scheme: dark;
  /* chrome & ink */
  --page: #0d0d0d;
  --surface: #1a1a19;
  --ink-1: #ffffff;
  --ink-2: #c3c2b7;
  --ink-3: #898781;
  --grid: #2c2c2a;
  --baseline: #383835;
  --border: rgba(255, 255, 255, 0.10);
  --hover-wash: rgba(255, 255, 255, 0.04);
  /* 分类色槽位（validated: adjacent & all-pairs PASS on dark） */
  --cat-1: #3987e5; /* 蓝 · 发版 */
  --cat-2: #d95926; /* 橙 · 配置 */
  --cat-3: #199e70; /* 绿松 · 扩缩容 */
  /* 状态色（固定，不参与主题） */
  --st-good: #0ca30c;
  --st-warning: #fab219;
  --st-serious: #ec835a;
  --st-critical: #d03b3b;
  /* 选中/强调（中性） */
  --accent: #3987e5;
  --accent-wash: rgba(57, 135, 229, 0.13);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--page);
  color: var(--ink-2);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---------- 头部（meta 区） ---------- */
.app-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-1);
  font-size: 14px;
  font-weight: 650;
  letter-spacing: 0.2px;
  white-space: nowrap;
}
.sys-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--st-good);
  box-shadow: 0 0 0 3px rgba(12, 163, 12, 0.18);
}
.env {
  font-size: 11px;
  font-weight: 500;
  color: var(--ink-3);
  border: 1px solid var(--baseline);
  border-radius: 4px;
  padding: 1px 6px;
}
.win { color: var(--ink-3); font-size: 12px; white-space: nowrap; }
.integrity {
  margin-left: auto;
  font-size: 12px;
  color: var(--ink-3);
  white-space: nowrap;
}
.integrity.ok::before { content: "●"; color: var(--st-good); margin-right: 6px; }
.integrity.bad::before { content: "●"; color: var(--st-critical); margin-right: 6px; }

/* ---------- 工具条（query 区） ---------- */
.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
  flex-wrap: nowrap;
  overflow-x: auto;
}
.chip-group { display: flex; gap: 6px; }
.tchip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: transparent;
  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 999px;
  padding: 3px 10px 3px 7px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  opacity: 0.45;
  transition: opacity 0.12s, border-color 0.12s;
}
.tchip.on { opacity: 1; border-color: var(--ink-3); }
.tchip:hover { background: var(--hover-wash); }
.tchip .glyph { font-size: 11px; }
.tchip .cnt { color: var(--ink-3); font-size: 11px; font-variant-numeric: tabular-nums; }
.comp-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-3);
  font-size: 12px;
  white-space: nowrap;
}
select {
  background: var(--surface);
  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 6px;
  padding: 3px 8px;
  font: inherit;
  font-size: 12px;
}
.ghost {
  background: transparent;
  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 6px;
  padding: 3px 10px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  white-space: nowrap;
}
.ghost:hover { background: var(--hover-wash); color: var(--ink-1); }
.spacer { flex: 1; }
.kbd-hint { color: var(--ink-3); font-size: 11.5px; white-space: nowrap; }
.kbd-hint b { color: var(--ink-2); font-weight: 600; }

/* ---------- 三栏工作区 ---------- */
.columns {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(460px, 1.3fr) minmax(340px, 1fr) minmax(370px, 1fr);
  gap: 10px;
  padding: 10px 12px 12px;
  min-height: 0;
}
.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}
.panel-head {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 9px 14px 8px;
  border-bottom: 1px solid var(--grid);
}
.panel-head h2 {
  margin: 0;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: var(--ink-3);
}
.panel-head .muted { font-size: 11.5px; }
.muted { color: var(--ink-3); }
.panel-body { flex: 1; overflow-y: auto; padding: 6px 0 14px; min-height: 0; }

/* ---------- 时间轴 ---------- */
.tl-canvas { position: relative; padding: 4px 14px 18px 30px; }
#edgeSvg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}
.edge {
  fill: none;
  stroke: var(--ink-3);
  stroke-width: 1.2;
  opacity: 0.4;
}
.tl-canvas.chain-on .edge { opacity: 0.12; }
.tl-canvas.chain-on .edge.edge-active {
  stroke: var(--accent);
  opacity: 1;
  stroke-width: 1.8;
}
.tl-canvas .edge.future-edge { opacity: 0.08; }

.day-group { position: relative; z-index: 1; }
.day-head {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 2px 6px;
  color: var(--ink-1);
}
.day-head h3 { margin: 0; font-size: 13px; font-weight: 650; letter-spacing: 0.4px; }
.day-sub { color: var(--ink-3); font-size: 11.5px; }
.day-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--baseline); }

.ev {
  position: relative;
  display: grid;
  grid-template-columns: 30px 1fr;
  padding: 4px 4px 4px 0;
  border-radius: 8px;
  cursor: pointer;
}
.ev:hover { background: var(--hover-wash); }
.ev.selected {
  background: var(--accent-wash);
  outline: 1px solid rgba(57, 135, 229, 0.55);
}
.ev.in-chain:not(.selected) { background: rgba(57, 135, 229, 0.06); }
.ev.future { opacity: 0.38; }
.ev.future .node { filter: saturate(0.25); }
.ev.hidden { display: none; }

/* 轨道竖线：连接本行节点到下一行节点 */
.ev-rail { position: relative; }
.ev-rail::before {
  content: "";
  position: absolute;
  left: 15px;
  top: 0;
  bottom: -4px;
  width: 2px;
  background: var(--grid);
}
.ev:last-child .ev-rail::before, .ev.future-last .ev-rail::before { display: none; }
.day-group:last-of-type .ev:last-child .ev-rail::before { display: none; }

.node {
  position: absolute;
  left: 7px;
  top: 9px;
  z-index: 2;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  background: var(--surface);
  border: 2px solid var(--ink-3);
  color: var(--ink-2);
}
.ev-main { min-width: 0; padding-right: 6px; }
.ev-line1 {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.ev-line1 time {
  color: var(--ink-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  flex: none;
}
.ev-title {
  color: var(--ink-1);
  font-weight: 550;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.badge {
  flex: none;
  font-size: 10.5px;
  padding: 0 6px;
  border-radius: 4px;
  border: 1px solid;
  line-height: 16px;
}
.ev-line2 {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 3px;
}

/* 类型着色：分类槽位 / 状态色，颜色只出现在标记（徽标边框、节点）上 */
.cat1 { border-color: var(--cat-1); color: var(--cat-1); }
.cat2 { border-color: var(--cat-2); color: var(--cat-2); }
.cat3 { border-color: var(--cat-3); color: var(--cat-3); }
.st-good { border-color: var(--st-good); color: var(--st-good); }
.st-warning { border-color: var(--st-warning); color: var(--st-warning); }
.st-serious { border-color: var(--st-serious); color: var(--st-serious); }
.st-critical { border-color: var(--st-critical); color: var(--st-critical); }

.node.cat1 { border-color: var(--cat-1); color: var(--cat-1); }
.node.cat2 { border-color: var(--cat-2); color: var(--cat-2); }
.node.cat3 { border-color: var(--cat-3); color: var(--cat-3); }
.node.st-good { border-color: var(--st-good); color: var(--st-good); }
.node.st-warning { border-color: var(--st-warning); color: var(--st-warning); }
.node.st-serious { border-color: var(--st-serious); color: var(--st-serious); }
.node.st-critical { border-color: var(--st-critical); color: var(--st-critical); }

/* chips */
.chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 10.5px;
  line-height: 17px;
  padding: 0 7px;
  border-radius: 999px;
  border: 1px solid var(--baseline);
  color: var(--ink-2);
  background: transparent;
}
.chip-comp { color: var(--ink-3); cursor: default; }
button.chip { cursor: pointer; font-family: inherit; }
button.chip:hover { background: var(--hover-wash); color: var(--ink-1); }
.chip-cause { border-color: rgba(236, 131, 90, 0.55); color: var(--st-serious); }
.chip-lead { border-color: rgba(57, 135, 229, 0.5); color: var(--cat-1); }

.empty {
  padding: 40px 20px;
  text-align: center;
  color: var(--ink-3);
}
.hidden { display: none !important; }

/* ---------- 检查器 ---------- */
.ins-guide { padding: 26px 18px; color: var(--ink-2); }
.ins-guide p { margin: 0 0 10px; }
.ins-head {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 14px 16px 0;
  color: var(--ink-1);
}
.ins-head h3 { margin: 1px 0 0; font-size: 14px; font-weight: 650; line-height: 1.4; }
.ins-meta {
  padding: 6px 16px 0;
  color: var(--ink-3);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.ins-detail { padding: 8px 16px 0; margin: 0; color: var(--ink-2); }
.ins-sec { padding: 14px 16px 0; }
.ins-sec h4 {
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 1.1px;
  text-transform: uppercase;
  color: var(--ink-3);
}
.diff-table, .snap-table { width: 100%; border-collapse: collapse; }
.diff-table td, .snap-table td {
  padding: 5px 8px 5px 0;
  border-bottom: 1px solid var(--grid);
  vertical-align: top;
}
.td-comp { color: var(--ink-2); white-space: nowrap; width: 1%; }
.td-field { color: var(--ink-3); white-space: nowrap; }
.td-diff, .td-val { color: var(--ink-1); text-align: right; }
.td-diff s, .td-val s { color: var(--ink-3); font-weight: 400; }
.td-diff b, .td-val b { font-weight: 650; }
.td-diff .arrow, .td-val .arrow { color: var(--ink-3); padding: 0 3px; }
.ins-cause-row { display: flex; gap: 8px; margin-bottom: 8px; }
.ins-label {
  flex: none;
  width: 34px;
  color: var(--ink-3);
  font-size: 12px;
  padding-top: 3px;
}
.ins-chips { display: flex; gap: 6px; flex-wrap: wrap; }
.ins-note { font-size: 11.5px; margin: 4px 0 0; }
.btn-align {
  margin: 16px 16px 4px;
  width: calc(100% - 32px);
  background: transparent;
  border: 1px solid var(--baseline);
  color: var(--ink-2);
  border-radius: 8px;
  padding: 7px 10px;
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
}
.btn-align:hover { background: var(--accent-wash); border-color: var(--accent); color: var(--ink-1); }

/* ---------- 快照 ---------- */
.cursor-box {
  padding: 9px 14px 10px;
  border-bottom: 1px solid var(--grid);
}
.cursor-read {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 6px;
}
#cursorLabel { color: var(--ink-1); font-weight: 600; font-size: 12.5px; font-variant-numeric: tabular-nums; }
#foldCount { font-size: 11.5px; }
input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
  margin: 2px 0 7px;
}
.cursor-btns { display: flex; gap: 6px; }
.snap-note {
  margin: 10px 14px 0;
  padding: 7px 10px;
  border: 1px solid rgba(250, 178, 25, 0.4);
  border-radius: 6px;
  color: var(--st-warning);
  font-size: 12px;
  background: rgba(250, 178, 25, 0.07);
}
.snap-note.muted {
  border-color: var(--grid);
  color: var(--ink-3);
  background: transparent;
}
.comp { padding: 10px 14px 2px; }
.comp + .comp { border-top: 1px solid var(--grid); margin-top: 8px; }
.comp-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}
.comp-name { color: var(--ink-1); font-weight: 650; }
.pill {
  font-size: 11px;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid;
  line-height: 17px;
}
.snap-table tr.hot td { background: var(--accent-wash); }
.snap-table tr.hot td:first-child { border-left: 2px solid var(--accent); padding-left: 6px; }

/* ---------- 错误横幅 / 焦点 ---------- */
.error-banner {
  background: rgba(208, 59, 59, 0.15);
  border-bottom: 1px solid var(--st-critical);
  color: #f0b6b6;
  padding: 8px 16px;
  font-size: 12.5px;
}
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}
.ev:focus-visible { outline-offset: -2px; }

/* 滚动条 */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: var(--baseline); border-radius: 5px; border: 2px solid var(--surface); }
::-webkit-scrollbar-track { background: transparent; }

