.ev-rail::before {
  content: "";
  position: absolute;
  left: 15px;
  top: 0;
  bottom: -4px;
  width: 2px;
  background: var(--grid);
}
.ev:last-child .ev-rail::before, .ev.future-last .ev-rail::before { display: none; }
.day-group:last-of-type .ev:last-child .ev-rail::before { display: none; }

.node {
  position: absolute;
  left: 7px;
  top: 9px;
  z-index: 2;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  background: var(--surface);
  border: 2px solid var(--ink-3);
  color: var(--ink-2);
}
.ev-main { min-width: 0; padding-right: 6px; }
.ev-line1 {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.ev-line1 time {
  color: var(--ink-3);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  flex: none;
}
.ev-title {
  color: var(--ink-1);
  font-weight: 550;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.badge {
  flex: none;
  font-size: 10.5px;
  padding: 0 6px;
  border-radius: 4px;
  border: 1px solid;
  line-height: 16px;
}
.ev-line2 {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-wrap: wrap;
  margin-top: 3px;
}

