:root {
  color-scheme: dark;
  /* chrome & ink */
  --page: #0d0d0d;
  --surface: #1a1a19;
  --ink-1: #ffffff;
  --ink-2: #c3c2b7;
  --ink-3: #898781;
  --grid: #2c2c2a;
  --baseline: #383835;
  --border: rgba(255, 255, 255, 0.10);
  --hover-wash: rgba(255, 255, 255, 0.04);
  /* 分类色槽位（validated: adjacent & all-pairs PASS on dark） */
  --cat-1: #3987e5; /* 蓝 · 发版 */
  --cat-2: #d95926; /* 橙 · 配置 */
  --cat-3: #199e70; /* 绿松 · 扩缩容 */
