  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 6px;
  padding: 3px 8px;
  font: inherit;
  font-size: 12px;
}
.ghost {
  background: transparent;
  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 6px;
  padding: 3px 10px;
