  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}
.edge {
  fill: none;
  stroke: var(--ink-3);
  stroke-width: 1.2;
  opacity: 0.4;
}
.tl-canvas.chain-on .edge { opacity: 0.12; }
.tl-canvas.chain-on .edge.edge-active {
  stroke: var(--accent);
  opacity: 1;
  stroke-width: 1.8;
}
.tl-canvas .edge.future-edge { opacity: 0.08; }
.tl-canvas .edge.edge-active.future-edge { opacity: 0.1; }

