        if (state.selectedId) {
          for (var i = 0; i < vis.length; i++) if (vis[i].id === state.selectedId) { curIdx = i; break; }
        }
        var next = vis[Math.max(0, Math.min(vis.length - 1, curIdx + step))];
        if (curIdx === -1) next = step > 0 ? vis[0] : vis[vis.length - 1];
