    });
    sec.appendChild(tbl);
    box.appendChild(sec);

    /* 因果上下文 */
    var sec2 = el("section", "ins-sec");
    sec2.appendChild(el("h4", null, "因果上下文"));
    var rowC = el("div", "ins-cause-row");
    rowC.appendChild(el("span", "ins-label", "起因"));
    var cwrap = el("div", "ins-chips");
