    note.textContent = "因果链共 " + chainIds.length + " 个关联事件，已在时间轴中连线高亮；连线方向与时间正方向一致。";
    sec2.appendChild(note);
    box.appendChild(sec2);

    var align = el("button", "btn-align");
    align.textContent = "⇥ 将游标对齐此事件（快照折叠到 " + fmtTime(ev.ts) + "）";
