    $("snapAt").textContent = "游标 " + (state.cursorIdx < 0 ? "窗口起点" : fmtHM(EVENTS[state.cursorIdx].ts));
    var box = $("snapshotBody");
    box.textContent = "";

    if (sel && !selApplicable) {
