          if (hit) {
            tr.classList.add("hot");
            var ch2 = sel.changes.filter(function (ch) { return ch.component === c.id && ch.field === f; })[0];
            td.textContent = "";
            td.appendChild(el("s", null, fmtVal(f, ch2.from)));
