    });
    $("tlShown").textContent = "显示 " + shown + "/" + EVENTS.length;
    $("tlEmpty").classList.toggle("hidden", shown !== 0);
    document.querySelectorAll("#tlCanvas .day-group").forEach(function (g) {
      var any = g.querySelectorAll(".ev:not(.hidden)").length > 0;
