    applyFilters();
  }

  /* ---------- 启动 ---------- */
  function buildToolbar() {
    var wrap = $("typeChips");
    var counts = {};
    EVENTS.forEach(function (ev) { counts[ev.type] = (counts[ev.type] || 0) + 1; });
    Object.keys(EVT).forEach(function (t) {
      var b = el("button", "tchip on");
