    selected: (document.querySelector("article.ev.selected")||{}).dataset?.id,
    inChain: [...document.querySelectorAll("article.ev.in-chain")].map(e=>e.dataset.id)
  })`)));

  // 真实点击检查器起因 chip
  const r = await ev(`(() => { const e = document.querySelector("#inspectorBody .chip-cause"); const b = e.getBoundingClientRect(); return {x:b.left+b.width/2, y:b.top+b.height/2}; })()`);
  for (const t of ["mouseMoved", "mousePressed", "mouseReleased"])
    await cdp("Input.dispatchMouseEvent", { type: t, x: r.x, y: r.y, button: "left", clickCount: t === "mouseMoved" ? 0 : 1 });
  await sleep(500);

  console.log("after click:", JSON.stringify(await ev(`({
    selected: (document.querySelector("article.ev.selected")||{}).dataset?.id,
    inChain: [...document.querySelectorAll("article.ev.in-chain")].map(e=>e.dataset.id),
    chainOn: document.getElementById("tlCanvas").classList.contains("chain-on")
  })`)));

  ws.close(); chrome.kill();
}
main().catch((e) => { console.error("FATAL", e); process.exit(1); });

