  const ev = async (expression) => (await cdp("Runtime.evaluate", { expression, returnByValue: true })).result.value;
  const snap = `(() => {
    const closure = (root) => { const set = new Set([root]); const st = [root];
      while (st.length) { const c = st.pop(); const e = window.DATA.events.find(x => x.id === c); if (!e) continue;
        (e.causes||[]).forEach(k => { if (!set.has(k)) { set.add(k); st.push(k);} });
        window.DATA.events.forEach(x => { if ((x.causes||[]).includes(c) && !set.has(x.id)) { set.add(x.id); st.push(x.id);} }); }
      return set; };
    const sel = (document.querySelector("article.ev.selected")||{}).dataset?.id || null;
    return { sel,
      inChain: [...document.querySelectorAll("article.ev.in-chain")].map(e=>e.dataset.id),
      expected: sel ? [...closure(sel)] : [],
      rowsTotal: document.querySelectorAll("article.ev").length };
  })()`;
  const realClickAt = async (x, y) => {
    for (const t of ["mouseMoved", "mousePressed", "mouseReleased"])
