  for (let i = 0; i < 60; i++) { try { await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json(); break; } catch { await sleep(250); } }
  const target = await (await fetch(`http://127.0.0.1:${PORT}/json/new?${encodeURIComponent(APP_URL)}`, { method: "PUT" })).json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  let id = 0; const pend = new Map();
  ws.onmessage = (ev) => { const m = JSON.parse(ev.data); if (m.id && pend.has(m.id)) { pend.get(m.id)(m); pend.delete(m.id); } };
  const cdp = (method, params = {}) => new Promise((res, rej) => { const i = ++id; pend.set(i, (m) => m.error ? rej(new Error(JSON.stringify(m.error))) : res(m.result)); ws.send(JSON.stringify({ id: i, method, params })); });
  const ev = async (expression) => (await cdp("Runtime.evaluate", { expression, returnByValue: true })).result.value;
  const snap = `(() => {
    const closure = (root) => { const set = new Set([root]); const st = [root];
      while (st.length) { const c = st.pop(); const e = window.DATA.events.find(x => x.id === c); if (!e) continue;
        (e.causes||[]).forEach(k => { if (!set.has(k)) { set.add(k); st.push(k);} });
        window.DATA.events.forEach(x => { if ((x.causes||[]).includes(c) && !set.has(x.id)) { set.add(x.id); st.push(x.id);} }); }
      return set; };
    const sel = (document.querySelector("article.ev.selected")||{}).dataset?.id || null;
    return { sel,
      inChain: [...document.querySelectorAll("article.ev.in-chain")].map(e=>e.dataset.id),
      expected: sel ? [...closure(sel)] : [],
      rowsTotal: document.querySelectorAll("article.ev").length };
  })()`;
  const realClickAt = async (x, y) => {
    for (const t of ["mouseMoved", "mousePressed", "mouseReleased"])
      await cdp("Input.dispatchMouseEvent", { type: t, x, y, button: "left", clickCount: t === "mouseMoved" ? 0 : 1 });
  };

  await cdp("Runtime.enable"); await cdp("Page.enable"); await sleep(600);

  console.log("初始:", JSON.stringify(await ev(snap)));

  // 点击检查器起因 chip（e06 的起因 e04）
  const chip = await ev(`(() => { const e = document.querySelector("#inspectorBody .chip-cause"); const b = e.getBoundingClientRect(); return {x:b.left+b.width/2, y:b.top+b.height/2}; })()`);
  await realClickAt(chip.x, chip.y); await sleep(400);
  console.log("chip跳转后:", JSON.stringify(await ev(snap)));

  // 直接点击时间轴 e07 行的标题区
  const row = await ev(`(() => { const e = document.querySelector('article.ev[data-id="e07"] .ev-title'); const b = e.getBoundingClientRect(); return {x:b.left+b.width/2, y:b.top+b.height/2}; })()`);
  await realClickAt(row.x, row.y); await sleep(400);
  console.log("行点击e07后:", JSON.stringify(await ev(snap)));

  // 再用 JS 合成 click 点击 e18 行
  await ev(`document.querySelector('article.ev[data-id="e18"]').click()`); await sleep(300);
  console.log("合成click e18后:", JSON.stringify(await ev(snap)));

  ws.close(); chrome.kill();
}
main().catch((e) => { console.error("FATAL", e); process.exit(1); });

