  --cat-1: #3987e5; /* 蓝 · 发版 */
  --cat-2: #d95926; /* 橙 · 配置 */
  --cat-3: #199e70; /* 绿松 · 扩缩容 */
  /* 状态色（固定，不参与主题） */
  --st-good: #0ca30c;
  --st-warning: #fab219;
  --st-serious: #ec835a;
  --st-critical: #d03b3b;
  /* 选中/强调（中性） */
  --accent: #3987e5;
  --accent-wash: rgba(57, 135, 229, 0.13);
}

