.st-critical { --mark: var(--st-critical); }

.node {
  color: var(--mark, var(--ink-2));
  border-color: var(--mark, var(--ink-3));
}

/* chips */
.chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 10.5px;
  line-height: 17px;
  padding: 0 7px;
  border-radius: 999px;
