      clearTimeout(rt);
      rt = setTimeout(drawEdges, 120);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot2);
  } else {
    boot2();
  }

  /* 调试/取证句柄（只读用途） */
  window.__AURORA = { state: state, chainOf: chainOf, ledTo: LED, events: EVENTS };
})();

