.btn-align {
  margin: 16px 16px 4px;
  width: calc(100% - 32px);
  background: transparent;
  border: 1px solid var(--baseline);
  color: var(--ink-2);
  border-radius: 8px;
  padding: 7px 10px;
  font: inherit;
  font-size: 12.5px;
  cursor: pointer;
