/* =====================================================================
 * AURORA 变更时间轴 — 样式（深色专业运维工具）
 *
 * 色彩通道分工（经 dataviz 校验器验证，dark surface #1a1a19）：
 *   分类色（中性操作：发版/配置/扩缩容）→ 校验通过的 3 槽位
 *   状态色（故障/回滚/修复、健康度）    → 固定状态色板，恒以 icon+label 出现
 *   文本一律用 ink 令牌，颜色只出现在标记上
 * ===================================================================== */

:root {
  color-scheme: dark;
  /* chrome & ink */
  --page: #0d0d0d;
  --surface: #1a1a19;
  --ink-1: #ffffff;
  --ink-2: #c3c2b7;
  --ink-3: #898781;
  --grid: #2c2c2a;
  --baseline: #383835;
  --border: rgba(255, 255, 255, 0.10);
  --hover-wash: rgba(255, 255, 255, 0.04);
  /* 分类色槽位（validated: adjacent & all-pairs PASS on dark） */
  --cat-1: #3987e5; /* 蓝 · 发版 */
  --cat-2: #d95926; /* 橙 · 配置 */
  --cat-3: #199e70; /* 绿松 · 扩缩容 */
  /* 状态色（固定，不参与主题） */
  --st-good: #0ca30c;
  --st-warning: #fab219;
  --st-serious: #ec835a;
  --st-critical: #d03b3b;
  /* 选中/强调（中性） */
  --accent: #3987e5;
  --accent-wash: rgba(57, 135, 229, 0.13);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--page);
  color: var(--ink-2);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---------- 头部（meta 区） ---------- */
.app-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-1);
  font-size: 14px;
  font-weight: 650;
  letter-spacing: 0.2px;
  white-space: nowrap;
}
.sys-dot {
  width: 9px; height: 9px; border-radius: 50%;
  background: var(--st-good);
  box-shadow: 0 0 0 3px rgba(12, 163, 12, 0.18);
}
.env {
  font-size: 11px;
  font-weight: 500;
  color: var(--ink-3);
  border: 1px solid var(--baseline);
  border-radius: 4px;
  padding: 1px 6px;
}
.win { color: var(--ink-3); font-size: 12px; white-space: nowrap; }
.integrity {
  margin-left: auto;
  font-size: 12px;
  color: var(--ink-3);
  white-space: nowrap;
}
.integrity.ok::before { content: "●"; color: var(--st-good); margin-right: 6px; }
.integrity.bad::before { content: "●"; color: var(--st-critical); margin-right: 6px; }

/* ---------- 工具条（query 区） ---------- */
.toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
  flex-wrap: nowrap;
  overflow-x: auto;
}
.chip-group { display: flex; gap: 6px; }
.tchip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 24px;
  background: transparent;
  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 999px;
  padding: 3px 10px 3px 7px;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  opacity: 0.65;
  transition: opacity 0.12s, border-color 0.12s;
}
.tchip.on { opacity: 1; border-color: var(--ink-3); }
.tchip:hover { background: var(--hover-wash); }
.tchip .glyph { font-size: 11px; color: var(--mark-text, var(--mark, var(--ink-2))); }
.tchip .cnt { color: var(--ink-3); font-size: 11px; font-variant-numeric: tabular-nums; }
.comp-filter {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--ink-3);
  font-size: 12px;
  white-space: nowrap;
}
select {
  background: var(--surface);
  color: var(--ink-2);
  border: 1px solid var(--baseline);
  border-radius: 6px;
  padding: 3px 8px;
  font: inherit;
  font-size: 12px;
}
.ghost {
