:root {
  color-scheme: dark;
  /* chrome & ink */
  --page: #0d0d0d;
  --surface: #1a1a19;
  --ink-1: #ffffff;
  --ink-2: #c3c2b7;
  --ink-3: #898781;
  --grid: #2c2c2a;
  --baseline: #383835;
  --border: rgba(255, 255, 255, 0.10);
  --hover-wash: rgba(255, 255, 255, 0.04);
  /* 分类色槽位（validated: adjacent & all-pairs PASS on dark） */
  --cat-1: #3987e5; /* 蓝 · 发版 */
  --cat-2: #d95926; /* 橙 · 配置 */
  --cat-3: #199e70; /* 绿松 · 扩缩容 */
  /* 状态色（固定，不参与主题） */
  --st-good: #0ca30c;
  --st-warning: #fab219;
  --st-serious: #ec835a;
  --st-critical: #d03b3b;
  /* 选中/强调（中性） */
  --accent: #3987e5;
  /* 强调底色：预先与 #1a1a19 混合为不透明色（半透明 wash 会使文字有效对比度不可控） */
  --accent-wash: #1e2834;
  --chain-wash: #1c2126;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
}

body {
  background: var(--page);
  color: var(--ink-2);
  font: 13px/1.5 system-ui, -apple-system, "Segoe UI", "Microsoft YaHei", sans-serif;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---------- 头部（meta 区） ---------- */
.app-header {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
}
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ink-1);
  font-size: 14px;
  font-weight: 650;
